#!/bin/bash

KATALOG="$HOME/raporty"
PLIK="$KATALOG/raport.txt"

mkdir -p "$KATALOG"
{
    echo "========================================"
    echo "Data: $(date '+%Y-%m-%d %H:%M:%S')"
    echo "----------------------------------------"
    echo "Lista procesów:"
    ps aux
    echo "----------------------------------------"
    echo "Raport zakończony o godzinie $(date '+%H:%M:%S')"
    echo "========================================"
    echo ""
} >> "$PLIK"

